const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '-10' },
      { kind: 'text', payload: '-6' },
      { kind: 'text', payload: '-2' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '6' },
      { kind: 'text', payload: '10' }
    ];
  },
  render: function (input, metrics) {
    var w = Number(input.viewport.widthDu) || 800;
    var h = Number(input.viewport.heightDu) || 400;
    var margin = Math.max(24, Math.min(w * 0.1, 80));
    var x0 = margin;
    var x1 = w - margin;
    if (x1 <= x0) {
      x0 = w * 0.05;
      x1 = w * 0.95;
    }
    var y = h * 0.58;
    if (y > h - 36) {
      y = Math.max(24, h - 48);
    }
    var tickLen = Math.max(5, Math.min(12, h * 0.045));
    var axisCommands = [['M', x0, y], ['L', x1, y]];
    var tickCommands = [];
    var xs = [];
    var i;
    for (i = 0; i < 6; i++) {
      var t = i / 5;
      var x = x0 + (x1 - x0) * t;
      xs.push(x);
      tickCommands.push(['M', x, y - tickLen], ['L', x, y + tickLen]);
    }
    var gap = Math.max(4, h * 0.02);
    var labelY = y + tickLen + gap;
    var labelVAlign = 'top';
    if (labelY > h - 10) {
      labelY = y - tickLen - gap;
      labelVAlign = 'bottom';
    }
    var labelNodes = [];
    for (i = 0; i < 6; i++) {
      labelNodes.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: xs[i], y: labelY },
        hAlign: 'center',
        vAlign: labelVAlign,
        color: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'axis_minus10_to_10_six_ticks',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'axis', commands: axisCommands },
        { id: 'ticks', commands: tickCommands }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 2 } }
        ].concat(labelNodes)
      }
    };
  }
};
